import React, { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api"; // Axios instance
import { AuthContext } from "../contexts/AuthContext";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const res = await api.post("/auth/login", { email, password });
      const { token, user } = res.data;

      if (!user || !token) {
        setError("Invalid response from server");
        return;
      }

      // If student, require TOTP
      if (user.role === "student") {
        localStorage.setItem("tempUser", JSON.stringify(user));
        localStorage.setItem("tempToken", token);
        navigate("/totp-setup");
        return;
      }

      // Admin / Comelec: login immediately
      login({ token, user });

      // Redirect based on role
      if (user.role === "admin") navigate("/admin-dashboard");
      else if (user.role === "comelec") navigate("/comelec-dashboard");
      else navigate("/login");

    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error || "Login failed. Please try again.");
    }
  };

  return (
    <div style={{ display: "flex", justifyContent: "center", padding: "50px", fontFamily: "Arial, sans-serif" }}>
      <div style={{
        width: "400px",
        padding: "30px",
        border: "1px solid #ddd",
        borderRadius: "10px",
        boxShadow: "0 4px 10px rgba(0,0,0,0.1)"
      }}>
        <h2 style={{ textAlign: "center", marginBottom: "20px", color: "#333" }}>Login</h2>
        <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
          />
          <button
            type="submit"
            style={{
              padding: "12px",
              borderRadius: "5px",
              border: "none",
              backgroundColor: "#007bff",
              color: "#fff",
              fontWeight: "bold",
              cursor: "pointer"
            }}
          >
            Login
          </button>
        </form>

        {error && <p style={{ marginTop: "20px", textAlign: "center", color: "red" }}>{error}</p>}

        <p style={{ marginTop: "20px", textAlign: "center", fontSize: "0.9rem", color: "#555" }}>
          Don't have an account?{" "}
          <button
            type="button"
            style={{ color: "#007bff", fontWeight: "bold", cursor: "pointer", background: "none", border: "none" }}
            onClick={() => navigate("/register")}
          >
            Register
          </button>
        </p>
      </div>
    </div>
  );
}
